# -*- coding: utf-8 -*-
"""Содержание сопровождения урока «Рациональные (алгебраические) дроби»: что говорить на каждом этапе.
Формат: S = [(заголовок этапа, минуты, экраны, [(метка, текст), ...]), ...]; ERR = [(ошибка, что сделать), ...]."""
S = []
def st(title, mins, scr, items): S.append((title, mins, scr, items))


st('Старт', '1–3', 'экраны 1–3', [
 ('Сказать', '«Сегодня знакомимся с рациональными, или алгебраическими, дробями. Это дроби, у которых в числителе и знаменателе многочлены, а внизу есть переменная. Научимся находить, при каких x дробь имеет смысл, сокращать её и выполнять действия. Идём маленькими шагами, подсказки есть, ошибаться можно.»'),
 ('Показать на экране 3', 'дробь (x² − 9)/(x² + 3x). «Как думаешь, её можно записать короче?» Дай подумать, не подсказывай. Ответ откроется кнопкой.'),
 ('Ответ', '(x − 3)/x. «Как это делать, разберём сегодня. Такие выражения встречаются в заданиях 8 и 20 ОГЭ.»'),
 ('На доске', '(x² − 9)/(x² + 3x) = (x − 3)/x'),
])
st('Повторяем: сокращение числовой дроби и общий множитель', '3–5', 'экраны 4–8', [
 ('Сказать', '«Дробь можно сократить, если числитель и знаменатель разделить на одно и то же число, не равное нулю. Разложим 12 и 18 на множители: 12 = 2 · 2 · 3, 18 = 2 · 3 · 3. Сокращаем одинаковые множители, остаётся 2/3.»'),
 ('Сказать', '«Если у всех слагаемых есть общий множитель, его выносят за скобки. 6x + 9 = 3(2x + 3). Проверяем: 3 · 2x + 3 · 3 = 6x + 9.»'),
 ('Ответы', 'экран 5: 18/30 = 3/5, ответ 3.\nЭкран 7: 4x − 8 = 4(x − 2), вариант 2.\nЭкран 8: x² + 5x = x(x + 5), вариант 1.'),
 ('Если ошибка', 'Если вынесла не весь общий множитель, спроси: «На что делятся оба числа?» Для x² + 5x спроси: «Какая буква есть в обоих слагаемых?»'),
 ('На доске', '6x + 9 = 3(2x + 3)'),
])
st('Повторяем: формулы сокращённого умножения и квадратный трёхчлен', '5–10', 'экраны 9–14', [
 ('Сказать (формулы)', '«Разность квадратов: a² − b² = (a − b)(a + b). Квадрат суммы: (a + b)² = a² + 2ab + b². Квадрат разности: (a − b)² = a² − 2ab + b².» Разбери x² − 9 = (x − 3)(x + 3).'),
 ('Сказать (трёхчлен)', '«Если у уравнения ax² + bx + c = 0 корни x₁ и x₂, то ax² + bx + c = a(x − x₁)(x − x₂).» Разбери x² − 5x + 6: D = 1, корни 2 и 3, значит, (x − 2)(x − 3).'),
 ('Ответы', 'экран 10: x² − 16 = (x − 4)(x + 4), вариант 2.\nЭкран 11: x² + 6x + 9 = (x + 3)², вариант 1.\nЭкран 13: x² − 7x + 10 = 0, больший корень 5 (корни 2 и 5).\nЭкран 14: x² − x − 6 = (x + 2)(x − 3), вариант 1.'),
 ('Если ошибка', 'Если выбрала (x − 4)² на экране 10, спроси: «Квадрат разности даёт среднее слагаемое. Есть ли оно в x² − 16?» В дискриминанте часто теряют знак у −4ac: «Минус на минус даёт плюс».'),
 ('Если времени мало', 'Если ученица уверенно раскладывает на множители, пролистай экраны 9–11 и оставь трёхчлен (12–14): он нужен в примере 5.'),
 ('На доске', 'a² − b² = (a − b)(a + b);  ax² + bx + c = a(x − x₁)(x − x₂)'),
])
st('Алгебраическая дробь и значение дроби', '10–13', 'экраны 15–19', [
 ('Сказать', '«Выражения 3x + 1 и x² − 5 называют целыми: в них нет деления на выражение с переменной. Выражения 5/x и (x + 1)/(x − 2) называют дробными. Целые и дробные вместе называют рациональными.»'),
 ('Сказать (определение)', '«Алгебраической, или рациональной, дробью называют дробь, числитель и знаменатель которой многочлены. Знаменатель не может быть равен нулю.»'),
 ('Показать', 'экран 18: дробь (x + 1)/(x − 2) при x = 5. «Числитель 6, знаменатель 3, значение 2.»'),
 ('Ответы', 'экран 17: переменная в знаменателе у 7/(y − 3), вариант 2.\nЭкран 19: (2x − 1)/(x + 1) при x = 3, ответ 1,25.'),
 ('Если ошибка', 'Если на экране 19 получила 5/3 или 3/5, спроси: «Что ты подставила вместо x в знаменатель?»'),
])
st('Допустимые значения и дробь, равная нулю', '13–19', 'экраны 20–27', [
 ('Сказать (определение)', '«Допустимыми называют те значения переменной, при которых выражение имеет смысл. У дроби это значения, при которых знаменатель не равен нулю.»'),
 ('Показать', 'экран 20: 5/(x − 2). «Знаменатель равен нулю при x = 2. Значит, x ≠ 2.» Экран 22: знаменатель из нескольких множителей, x ≠ 1 и x ≠ −4. «Достаточно, чтобы один множитель был нулём.»'),
 ('Сказать (дробь равна нулю)', '«Дробь равна нулю тогда и только тогда, когда числитель равен нулю, а знаменатель не равен нулю.» Разбери (x² − 4)/(x − 2) = 0: числитель равен нулю при x = 2 и x = −2, но x = 2 запрещено. Остаётся x = −2.'),
 ('Ответы', 'экран 21: 5/(x + 3) не имеет смысла при x = −3.\nЭкран 23: x² − 16 = (x − 4)(x + 4), запрещены два значения, ответ 2.\nЭкран 24: запрещены 2 и −5, сумма −3.\nЭкран 26: (x − 5)/(x + 2) = 0 при x = 5, вариант 2.\nЭкран 27: (x² − 9)/(x + 3) = 0 только при x = 3.'),
 ('Если ошибка', 'На экране 27 часто пишут «3 и −3». Спроси: «Что с корнем −3, не обращает ли он знаменатель в нуль?»'),
 ('На доске', 'знаменатель ≠ 0;  дробь = 0, если числитель = 0 и знаменатель ≠ 0'),
])
st('Основное свойство дроби и сокращение: примеры 1 и 2', '19–24', 'экраны 28–34', [
 ('Сказать (свойство)', '«Если числитель и знаменатель дроби умножить или разделить на один и тот же многочлен, не равный нулю, получится дробь, равная данной. На этом основано сокращение.»'),
 ('Сказать (алгоритм)', '«Сокращаем в четыре шага: разложили на множители, нашли одинаковые, сократили, записали остаток. Сокращать можно только множители, слагаемые нельзя.» Прочитайте таблицу на экране 30 вместе.'),
 ('Показать', 'экран 31: 6x²/(9x) = 2x/3. Экран 33: (3x + 6)/(x² + 2x) = 3(x + 2)/(x(x + 2)) = 3/x.'),
 ('Ответы', 'экран 29: x/5, умноженное на 3, даёт 3x/15, вариант 1.\nЭкран 32: 8a³/(12a) = 2a²/3, вариант 1.\nЭкран 34: (5x − 10)/(x − 2) = 5.'),
 ('Если ошибка', 'Если на экране 34 не получилось, покажи: «Сначала вынеси 5 за скобки в числителе, получится 5(x − 2). Теперь видно одинаковый множитель».'),
 ('На доске', 'a/b = (a · c)/(b · c), c ≠ 0'),
])
st('Сокращение: примеры 3, 4 и 5', '24–30', 'экраны 35–41', [
 ('Сказать', '«Пример 3: x² − 9 = (x − 3)(x + 3), x² + 3x = x(x + 3). Сокращаем (x + 3), остаётся (x − 3)/x. Это та дробь, с которой начинали урок.»'),
 ('Сказать', '«Пример 4: x² − 4x + 4 = (x − 2)², x² − 4 = (x − 2)(x + 2). Остаётся (x − 2)/(x + 2). Пример 5: числитель x² − 5x + 6 = (x − 2)(x − 3) мы раскладывали в начале. Остаётся (x − 3)/(x + 2).»'),
 ('Ответы', 'экран 36: (x² − 25)/(x + 5) = x − 5, вариант 1.\nЭкран 37: (x² − 4)/(x² + 2x) = (x − 2)/x, вариант 1.\nЭкран 39: (x² + 6x + 9)/(x² − 9) = (x + 3)/(x − 3), вариант 1.\nЭкран 41: (x² − 7x + 10)/(x² − 25) = (x − 2)/(x + 5), вариант 1.'),
 ('Если ошибка', 'Если сократила только часть множителя, например (x + 3) с x, спроси: «Это множитель или слагаемое?» Если на экране 41 неверно разложила числитель, вернись на экран 12 и найди корни через дискриминант.'),
 ('Если времени мало', 'Пример 4 (экраны 38–39) можно разобрать устно, но пример 5 (трёхчлен) не пропускай.'),
 ('На доске', '(x² − 9)/(x² + 3x) = (x − 3)(x + 3)/(x(x + 3)) = (x − 3)/x'),
])
st('Ловушки при сокращении', '30–33', 'экраны 42–49', [
 ('Ловушка 1 (экраны 42–43)', 'Сокращение слагаемых: (x + 2)/2 ≠ x. Проверка при x = 4: слева 3, справа 4. «Сокращать можно только множители.» Ответ на экране 43: верна запись 3x/3 = x (вариант 2).'),
 ('Ловушка 2 (экраны 44–46)', 'Противоположные выражения: a − b = −(b − a). Экран 45: (x − 5)/(5 − x) = −1. Экран 46: (x² − 4)/(2 − x) = −(x + 2), вариант 1.'),
 ('Ловушка 3 (экраны 47–48)', 'Допустимые значения после сокращения. «(x² − 9)/(x − 3) = x + 3, но при x = 3 исходная дробь не имеет смысла.» Ответ на экране 48: 3.'),
 ('Сказать', '«Допустимые значения всегда смотрим по исходной дроби, а не по той, что получилась после сокращения.»'),
 ('Экран 49', 'Короткий итог первой половины урока. Попроси ученицу своими словами назвать три правила: знаменатель не равен нулю, сокращаем множители, a − b = −(b − a).'),
])
st('Умножение, деление и степень дроби', '33–40', 'экраны 50–59', [
 ('Сказать (умножение)', '«Чтобы умножить дробь на дробь, перемножаем числители и знаменатели. Но сначала раскладываем на множители и сокращаем.» Разбери x/3 · 6/x² = 2/x.'),
 ('Сказать (деление)', '«Чтобы разделить одну дробь на другую, первую умножаем на дробь, обратную второй.» Разбери x/5 : x²/10 = x/5 · 10/x² = 2/x.'),
 ('Сказать (степень)', '«Чтобы возвести дробь в степень, возводим в эту степень числитель и знаменатель.» (2/x)³ = 8/x³.'),
 ('Ответы', 'экран 51: a/4 · 8/a³ = 2/a², вариант 1.\nЭкран 53: (x + 1)/(x − 1) · (x² − 1)/(x + 1) при x = 4, ответ 5.\nЭкран 55: 3/x : 6/x² = x/2, вариант 1.\nЭкран 57: (x² − 9)/(x + 2) : (x + 3)/(x + 2) = x − 3, вариант 1.\nЭкран 59: (3/y)² = 9/y², вариант 1.'),
 ('Если ошибка', 'При делении часто переворачивают первую дробь. Спроси: «Какую дробь меняем на обратную, первую или вторую?» На экране 53 советуй сначала упростить, потом подставлять.'),
 ('На доске', 'a/b · c/d = ac/(bd);  a/b : c/d = a/b · d/c;  (a/b)ⁿ = aⁿ/bⁿ'),
])
st('Сложение и вычитание с одинаковыми знаменателями', '40–44', 'экраны 60–64', [
 ('Сказать', '«Чтобы сложить дроби с одинаковыми знаменателями, складываем числители, знаменатель оставляем. Пример: (x + 3)/(x − 1) + (x − 5)/(x − 1) = (2x − 2)/(x − 1) = 2.»'),
 ('Сказать (вычитание)', '«При вычитании числитель второй дроби берём в скобки, иначе потеряем знак. (x + 5)/(x − 2) − (x + 1)/(x − 2) = (x + 5 − (x + 1))/(x − 2) = 4/(x − 2).»'),
 ('Ответы', 'экран 61: 2x/(x + 1) + 2/(x + 1) = 2, вариант 1.\nЭкран 63: (3x + 2)/x − (x + 2)/x = 2, вариант 1.\nЭкран 64: (5x + 1)/(x − 3) − (2x + 10)/(x − 3) = 3.'),
 ('Если ошибка', 'Самая частая ошибка: x + 5 − x + 1 вместо x + 5 − x − 1. «Минус перед скобкой меняет знак у каждого слагаемого в ней.» Если выбрала (2x + 4)/x на экране 63, покажи этот же знак.'),
 ('На доске', 'a/c − b/c = (a − b)/c, числитель вычитаемого в скобках'),
])
st('Сложение и вычитание с разными знаменателями', '44–50', 'экраны 65–75', [
 ('Сказать', '«Если знаменатели разные, приводим дроби к общему знаменателю, как у обыкновенных. 1/6 + 1/4 = 2/12 + 3/12 = 5/12. Здесь так же: 2/x + 3/(2x), общий знаменатель 2x.»'),
 ('Показать (экран 68)', '1/(x − 2) − 1/(x + 2). Общий знаменатель (x − 2)(x + 2). Числитель (x + 2) − (x − 2) = 4. Ответ 4/(x² − 4). «Скобки раскрываем аккуратно.»'),
 ('Показать (экран 71)', '3/(x − 2) + 5/(x² − 4). Раскладываем x² − 4 = (x − 2)(x + 2). У первой дроби дополнительный множитель (x + 2). Ответ (3x + 11)/(x² − 4).'),
 ('Показать (экран 74)', 'целое выражение: 2 − 3/(x + 1) = (2(x + 1) − 3)/(x + 1) = (2x − 1)/(x + 1).'),
 ('Ответы', 'экран 66: 1/(2x) + 1/(3x) = 5/(6x), вариант 1.\nЭкран 67: 3/a − 1/(2a) = 5/(2a), вариант 1.\nЭкран 69: 1/(x − 1) + 1/(x + 1) = 2x/(x² − 1), вариант 1.\nЭкран 70: 2/(x − 3) − 1/x = (x + 3)/(x(x − 3)), вариант 1.\nЭкран 72: 2/(x − 1) + 3/(x² − 1) = (2x + 5)/(x² − 1), вариант 1.\nЭкран 73: при x = 3 значение 0,8.\nЭкран 75: 3 + 1/(x − 1) = (3x − 2)/(x − 1), вариант 1.'),
 ('Если ошибка', 'Если сложила числители и знаменатели по отдельности, вернись на экран 65 и вспомни 1/6 + 1/4. Если не умножила число без дроби на знаменатель (экран 75), покажи: «3 = 3(x − 1)/(x − 1)».'),
 ('Если времени мало', 'Экраны 71–72 (знаменатель раскладывается) можно оставить на домашнее. Экран 74–75 (целое и дробь) тоже можно перенести.'),
 ('На доске', '1/(x − 2) − 1/(x + 2) = ((x + 2) − (x − 2))/((x − 2)(x + 2)) = 4/(x² − 4)'),
])
st('Смешанные примеры и поиск ошибки', '50–55', 'экраны 76–82', [
 ('Показать (экран 76)', '1/(x − 3) − 6/(x² − 9) = (x + 3 − 6)/((x − 3)(x + 3)) = (x − 3)/((x − 3)(x + 3)) = 1/(x + 3).'),
 ('Ответы', 'экран 77: при x = 1 значение 0,25.\nЭкран 78: выражение не имеет смысла при x = 3 и при x = −3, вариант 3.\nЭкран 80: (x² − 9)/(x − 1) : (x + 3)/(x² − 1) = (x − 3)(x + 1), при x = 4 ответ 5.\nЭкран 82: ошибка в знаке у слагаемого 1 во втором числителе, вариант 1. Верный ответ 4/(x − 2).'),
 ('Если ошибка', 'На экране 78 часто выбирают «только x = −3», глядя на сокращённую дробь 1/(x + 3). «Допустимые значения смотрим по исходному выражению.»'),
 ('Сказать', '«Теперь смотрим на чужое решение и ищем ошибку. Это самая частая ошибка в вычитании дробей, ты её уже знаешь.»'),
])
st('Алгоритм, шпаргалка, итоговые задачи', '55–60', 'экраны 83–91', [
 ('Сказать (экран 83)', '«Соберём всё в правило. Первое: допустимые значения. Второе: раскладываем на множители. Третье: выполняем действие. Четвёртое: сокращаем. Пятое: пишем ответ.» Затем: «Закрой экран и назови шаги по памяти.»'),
 ('Ответ', 'экран 84: перед сокращением раскладываем числитель и знаменатель на множители, вариант 1.'),
 ('Шпаргалка (экран 85)', 'Прочитай вместе, попроси переписать в тетрадь или сфотографировать.'),
 ('Итоговые 5 задач (экраны 87–91)', 'Ученица решает сама, ты не подсказываешь. Ответы: 3; −5; 0,6; 0,25; 0,5.\nЭкран 87: (x² − 16)/(x² − 4x) = (x + 4)/x, при x = 2 значение 3.\nЭкран 88: запрещены 2 и −7, сумма −5.\nЭкран 89: (x − 2)/(x + 2) при x = 8 равно 0,6.\nЭкран 90: 2/(x² − 1) при x = 3 равно 0,25.\nЭкран 91: 3/(x + 2) при x = 4 равно 0,5.'),
 ('Оценка результата', 'Предложение, не проверено на практике: 4–5 верно из 5 без подсказок — тема усвоена. 3 и меньше — вернуться к блокам: допустимые значения (экраны 20–27), сокращение (28–41), вычитание со скобками (62–64).'),
])

ERR = [
 ('Сократила слагаемые, а не множители: (x + 2)/2 = x', 'Вернись на экран 42. Подставь x = 4 и сравни: слева 3, справа 4. «Сокращаем только множители».'),
 ('Не разложила числитель или знаменатель перед сокращением', 'Покажи алгоритм на экране 30: сначала раскладываем, потом сокращаем.'),
 ('Не заметила, что a − b и b − a противоположные', 'Вернись на экран 44. «Выносим минус: 3 − x = −(x − 3)».'),
 ('Потеряла знак при вычитании дробей: x + 5 − x + 1', 'Вернись на экран 62. «Числитель второй дроби берём в скобки, минус меняет знак у каждого слагаемого».'),
 ('Нашла допустимые значения по сокращённой дроби', 'Вернись на экран 47. «Смотрим на исходное выражение, а не на результат».'),
 ('При делении перевернула не ту дробь', 'Вернись на экран 54. «Обратной делаем вторую дробь, первую не трогаем».'),
 ('Сложила числители и знаменатели по отдельности', 'Вернись на экран 65: 1/6 + 1/4. «Сначала общий знаменатель, потом числители».'),
]


TITLE = 'Рациональные (алгебраические) дроби · сопровождение урока'
SUB = '8 класс · 60 минут · средний уровень · для преподавателя. Интерактивный урок: obyasnenie-8-ratsionalnye-drobi.html (91 экран, 50 вопросов).'
SKIP = 'Пролистай экраны 9–11, если ученица уверенно раскладывает на множители. Пример 4 (экраны 38–39) разбери устно. Экраны 71–75 (знаменатель раскладывается, целое и дробь) перенеси на следующее занятие. Не пропускай допустимые значения (20–27), пример 5 (трёхчлен), ловушки (42–48) и вычитание со скобками (62–64).'
OUT = 'soprovozhdenie-uroka-ratsionalnye-drobi'
